// ============================================
// VALIDATION INPUT - MCP Tenant Resolve v2.0
// RFC-079: tenant + package + models
// ============================================

const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

const errors = [];

const action = body.action || ctx.action;
const userId = body.user_id || ctx.user_id || '';  // optionnel (RFC-079)
const guildId = body.guild_id || ctx.guild_id;
const backendApiUrl = body.backend_api_url || ctx.backend_api_url;
const backendServiceToken = body.backend_service_token || ctx.backend_service_token;

if (!action || action !== 'resolve') errors.push('action must be "resolve"');
// user_id est optionnel - pas de validation
if (!guildId) errors.push('guild_id requis');
if (!backendApiUrl) errors.push('backend_api_url requis');
if (!backendServiceToken) errors.push('backend_service_token requis');

if (errors.length > 0) {
  return { valid: false, errors, user_id: userId, guild_id: guildId };
}

return {
  valid: true,
  user_id: userId,
  guild_id: guildId,
  backend_api_url: backendApiUrl,
  backend_service_token: backendServiceToken,
  startTime: Date.now()
};

const input = $input.first().json;
return {
  success: false,
  error: { code: 'VALIDATION_ERROR', message: input.errors.join(', ') },
  user_id: input.user_id,
  guild_id: input.guild_id
};

// Format response for RFC-079 Phase 2 (tenant + package + models)
// Ref: chatbot_core/models/tenant_config.py TenantConfig.from_webhook_response
const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const latencyMs = Date.now() - (prevData.startTime || Date.now());

// Handle array response from API
const apiData = Array.isArray(input) ? input[0] : input;

// Check for HTTP error
if (input.error || input.statusCode >= 400) {
  const errorCode = input.error?.code || 'API_ERROR';
  return {
    success: false,
    error: { 
      code: errorCode, 
      message: input.error?.message || input.message || 'API call failed' 
    },
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    latency_ms: latencyMs
  };
}

// Validate RFC-079 required fields
if (!apiData.tenant_id) {
  return {
    success: false,
    error: { code: 'INVALID_RESPONSE', message: 'Missing tenant_id in API response' },
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    latency_ms: latencyMs
  };
}

// Return RFC-079 Phase 2 compliant response
// Structure explicite pour chatbot-core TenantConfig
return {
  success: true,
  data: {
    tenant_id: apiData.tenant_id,
    package: apiData.package ? {
      code: apiData.package.code,
      source: apiData.package.source,
      enforce: apiData.package.enforce ?? true,
      models: {
        chat: apiData.package.models?.chat || null,
        chat_mini: apiData.package.models?.chat_mini || null,
        embedding: apiData.package.models?.embedding || null,
        vision: apiData.package.models?.vision || null,
        voice: apiData.package.models?.voice || null,
        reasoning: apiData.package.models?.reasoning || null
      }
    } : null
  },
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
  latency_ms: latencyMs
};

